def test_an_unmeasured_egg_holder_is_a_valid_attrition_last_seat():
    """Owner (2026-10-30): 弱い将軍をたくさん送って少しずつ削る選択肢も狭めない.
    A general with an observed egg but no reference-table entry was dropped by
    _hero_alternatives' max_hp gate and could never join a boss sortie. It now
    goes after every measured general."""
    order = site_order()
    mem = memory()
    mem['egg_types']['ランダム将軍'] = 'どうし'      # observed egg, no table entry
    mem['egg_uses']['ランダム将軍'] = 3
    # The site rule still keeps an egg-holder behind: sending ランダム将軍
    # would leave eggless カペリーニ alone, so nobody goes.
    assert orders._order_hero_alternatives(order, mem, ['ランダム将軍', 'カペリーニ']) == []
    # With an egg-holder guard the unmeasured general is the attrition seat
    # behind the measured (weaker-than-boss) ブカティーニ.
    assert orders._order_hero_alternatives(order, mem, ['ランダム将軍', 'ブカティーニ']) == ['ブカティーニ', 'ランダム将軍']
    # A strong general still leads alone.
    assert orders._order_hero_alternatives(order, mem, ['ゼウス', 'ランダム将軍']) == ['ゼウス']
    # A spent egg does not go — and cannot guard either, so nobody leaves.
    mem['egg_uses']['ランダム将軍'] = 0
    assert orders._order_hero_alternatives(order, mem, ['ランダム将軍', 'ブカティーニ']) == []


def test_an_exhausted_site_step_rearms_after_a_long_stale_wait():
    """Owner 2026-10-30: a relaunch budget of 2 parks a site forever once its
    sorties never produce a measured entry; g1075 showed all four steps
    overdue+launched for 10h+ with nobody marching. A very long stale wait
    re-arms one retry so the chapter is never abandoned mid-attrition."""
    order = site_order()
    step = order['step']
    mem = memory()
    _plan_region(mem)['orders'][step] = 'launched'
    _world(mem)['sorties'] = {step: {'general': 'カペリーニ', 'source': 'ミヒラギアン',
                             'target': order['target'], 'status': 'overdue', 'tick': 100}}
    mem['boss_relaunch'] = {step: 2}
    mem['tick'] = 100 + orders.BOSS_STALE_COOLDOWN - 1
    orders._relaunch_overdue_boss(mem)
    assert _plan_region(mem)['orders'][step] == 'launched'              # still cooling down
    mem['tick'] = 100 + orders.BOSS_STALE_COOLDOWN
    orders._relaunch_overdue_boss(mem)
    assert _plan_region(mem)['orders'][step] == 'pending' and mem['boss_relaunch'][step] == 1


def test_a_measured_boss_entry_rearms_the_relaunch_budget():
    """A real entry is progress, not another black-hole cycle: binding it
    clears the step's relaunch count so later unresolved cycles can retry."""
    order = site_order()
    step = order['step']
    mem = memory()
    mem['boss_relaunch'] = {step: 2}
    _world(mem)['sorties'] = {step: {'general': 'ヴィーナス', 'source': 'アルカ',
                             'target': order['target'], 'status': 'en_route', 'tick': 50}}
    orders._bind_sortie(mem, step, order['target'])
    assert _world(mem)['sorties'][step]['status'] == 'arrived'
    assert mem['boss_relaunch'].get(step) is None
